module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] count_reg = 2'b00;

    always @(posedge clk) begin
        if (reset) begin
            count_reg <= 2'b11;
        end else if (count_reg != 2'b11) begin
            count_reg <= count_reg + 1;
        end
    end

    assign state = (reset == 1'b0) ? count_reg : 2'bzz;
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter [1:0] CONSTANT = 2'b00;
    reg [1:0] val2_reg;
    reg [1:0] val2_next;

    always @(*) begin
        val2_next = reset ? (CONSTANT + 2'd1) : CONSTANT;
    end

    always @(posedge clk) begin
        val2_reg <= val2_next;
    end

    assign state = val2_reg;
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [2:0] internal_wire;

    always @(posedge clk) begin
        if (reset) begin
            // Update lower two bits with 3 +1 (3'd3), upper bit remains 0
            internal_wire[1:0] <= 2'd3 + 2'd1;
        end else begin
            // Update lower two bits with 1 +1 (3'd1), upper bit remains 0
            internal_wire[1:0] <= 2'd1 + 2'd1;
        end
    end

    // Concatenate 1'b0 and lower two bits of the internal wire
    assign state = {1'b0, internal_wire[1:0]};

endmodule

module fsm_3state (
