    assign sum = val_2_reg + {2{reset}};
    assign state = sum;

    always @(posedge clk) begin
        if (sum[1])
            val_2_reg <= 2'b00;
        else
            val_2_reg <= sum;
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [2:0] internal_reg = 3'b000;

    always @(posedge clk) begin
        if (reset) begin
            internal_reg <= 3'b111;
        end else begin
            // Update lower two bits with current {1'b0, reset, reset} (reset XOR reset = reset)
            internal_reg <= {1'b0, reset, reset};
        end
    end

    assign state = {internal_reg[2], internal_reg[1] ^ internal_reg[0]};

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State definitions
    localparam [2:0] IDLE = 3'b000,
                     S1   = 3'b001,
                     S2   = 3'b010,
                     S3   = 3'b011;

    reg [2:0] state_reg, next_state;

    // State register update
    always @(posedge clk) begin
        state_reg <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state_reg)
            IDLE: next_state = reset ? S1 : IDLE;
            S1:   next_state = reset ? S2 : IDLE;
            S2:   next_state = reset ? S3 : IDLE;
            S3:   next_state = reset ? S3 : IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Output assignment
    assign light = (next_state == IDLE) ? 3'b111 :
                  (next_state == S1)   ? 3'b001 :
                  (next_state == S2)   ? 3'b010 :
                  (next_state == S3)   ? 3'b011 :
                  3'b111;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // Define states with 3-bit encoding (one-hot)
    localparam [2:0] 
        s0     = 3'b001,
        s1     = 3'b010,
        s110  = 3'b100; // Example state for reset high, clk low

    reg [2:0] current_state, next_state;

    // State register (sequential logic)
    always @(posedge clk) begin
        current_state <= next_state;
    end

    // Next state logic (combinational)
    always @(*) begin
        case ({reset, clk})
            2'b00:   next_state = s0;
            2'b01:   next_state = s1;
            2'b10:   next_state = s110;
            default: next_state = s0;
        endcase
    end

    // Output assignment (combinational)
    assign light = current_state;

endmodule

module traffic_light (
