);

localparam [2:0] 
    s0 = 3'b000,
    s1 = 3'b001,
    s2 = 3'b010,
    s3 = 3'b011;

reg [2:0] current_state, next_state;

// State transition on rising edge of clk
always @(posedge clk) begin
    current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        s0: next_state = reset ? s1 : s0;
        s1: next_state = reset ? s2 : s1;
        s2: next_state = reset ? s3 : s2;
        s3: next_state = reset ? s0 : s3;
        default: next_state = s0;
    endcase
end

// Output assignment
assign light = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [1:0] current_state, next_state;
    localparam [1:0]
        s0 = 2'b00,
        s1 = 2'b01,
        s2 = 2'b10;

    always @(posedge clk) begin
        current_state <= next_state;
    end

    always @(*) begin
        if (reset) begin
            case (current_state)
                s0: next_state = s1;
                s1: next_state = s2;
                s2: next_state = s0;
                default: next_state = s0;
            endcase
        end else begin
            next_state = s0;
        end
    end

    assign light = current_state + 3'd1;

    initial begin
        current_state = s0;
    end
endmodule

module traffic_light (
