        2'b10: next_state = reset ? 2'b11 : 2'b10;
        2'b11: next_state = reset ? 2'b00 : 2'b11;
        2'b00: next_state = reset ? 2'b01 : 2'b00;
        default: next_state = 2'b01;
    endcase
end

assign light[0] = (current_state == 2'b01);
