module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

reg [1:0] stored_val;

// Update stored value on rising edge of clk or reset (priority to clk)
always @(posedge clk, posedge reset) begin
    if (clk)
        stored_val <= {up_request, down_request};
    else if (reset)
        stored_val <= {up_request, ~down_request};
    else
        stored_val <= 2'b00;
end

// Output logic with 10ns delay for state[1]
assign #10 state = (clk & (stored_val == 2'b10)) ? 2'b11 :
                   (reset & (stored_val == 2'b10)) ? 2'b10 :
                   2'b00;

endmodule

module elevator_controller (
    input clk, reset,
