module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    reg [1:0] latched_val;

    // Latch the input pair when up_request is high
    always @(posedge up_request or posedge 0) begin
        if (up_request)
            latched_val <= {reset, clk};
    end

    // Determine output based on latched value and down_request
    assign state = ((latched_val == 2'b01) || (latched_val == 2'b10)) ? 2'b11 :
                   (down_request ? 2'b10 : 2'b01);

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    reg [1:0] current_state, next_state;

    // State register with asynchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= 2'b00;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            2'b00: next_state = up_request ? 2'b01 : 2'b00;
            2'b01: next_state = down_request ? 2'b10 : 2'b01;
            2'b10: next_state = 2'b11;
            2'b11: next_state = 2'b11;
            default: next_state = 2'b00;
        endcase
    end

    // Output logic
    assign state = (current_state == 2'b00) ? 2'b00 :
                   (current_state == 2'b01) ? 2'b01 :
                   (current_state == 2'b10) ? 2'b10 : 2'b00;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] state;
reg [1:0] val_8;

// Combinational logic for state
always @(*) begin
    if (coin_inserted)
        state = 2'd3;
    else if (item_selected)
        state = 2'd1;
    else if (clk)
        state = 2'd0;
    // Else, retain current value (inferred latch)
end

// Register val_8 when reset is high
always @(posedge reset) begin
    val_8 <= state;
end

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [2:0] r;
    wire [2:0] next_r;

    // Combinational logic for next register state
    assign next_r = coin_inserted ? (
        item_selected ? (
            clk ? r + 1 : r - 1 : 3'bx
        end
        : (
            clk ? r + 1 : r - 1 : 3'bx
        end
    )
    : (
        clk ? (
            reset ? r + 1 : r - 1 : 3'bx
        end
        : (
            reset ? r + 1 : r - 1 : 3'bx
        end
    );

    // Update register on positive edge of clk
    always @(posedge clk) begin
        if (reset)
            r <= next_r;
        else if (coin_inserted)
            r <= 3'b0;
    end

    // Output assignment based on item_selected
    assign state = item_selected ? r[1:0] : {2{r[2]}};

    // Initialize registers
    initial begin
        r = 3'b0;
    end
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] latched_val;
    reg [1:0] counter;

    always @(posedge coin_inserted or posedge item_selected) begin
        if (item_selected) begin
            latched_val <= 2'b00;
            counter <= 2'b00;
        end else begin
            latched_val <= {latched_val[0] | reset, latched_val[1] | clk};
            counter <= (counter == 2'b11) ? 2'b00 : counter + 1;
        end
    end

    assign state = clk ? latched_val : 2'b00;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] internal_reg = 2'b00;
    reg temp;

    always @(*) begin
        case ({coin_inserted, item_selected})
            2'b01: temp = reset;
            2'b10: temp = reset + 1;
            2'b11: temp = reset + 2;
            default: temp = reset;
        endcase
    end

    always @(posedge clk) begin
        if (coin_inserted)
            internal_reg <= 2'b00;
        else if (item_selected)
            internal_reg <= temp;
    end

    assign state = reset ? internal_reg : 2'bzz;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] reg1 = 2'b00;
reg [1:0] reg2 = 2'b00;
reg [1:0] reg3 = 2'b00;
reg [1:0] reg4 = 2'b00;

always @(posedge clk, posedge reset) begin
    if (reset)
        reg1 <= 2'b00;
    else
        reg1 <= reg2;
end

always @(posedge clk, posedge coin_inserted) begin
    if (coin_inserted)
        reg2 <= 2'b00;
    else
        reg2 <= reg3;
