    // 3-to-8 decoder for shift (active-high one-hot)
    always @(*) begin
        case (shift)
            3'b000: seg1 = 8'b00000001;
            3'b001: seg1 = 8'b00000010;
            3'b010: seg1 = 8'b00000100;
            3'b011: seg1 = 8'b00001000;
            3'b100: seg1 = 8'b00010000;
            3'b101: seg1 = 8'b00100000;
            3'b110: seg1 = 8'b01000000;
            3'b111: seg1 = 8'b10000000;
            default: seg1 = 8'b00000001; // Handles undefined cases
        endcase
    end

    // 1-bit to 8-bit decoder for in (active-high one-hot)
    always @(*) begin
        case (in)
            1'b0: seg0 = 8'b00000001;
            1'b1: seg0 = 8'b00000010;
            default: seg0 = 8'b00000001; // Handles undefined cases
        endcase
    end

    // Combine the outputs and invert
    assign out = ~(seg1 | seg0);

endmodule

