    wire [3:0] val_4_intermediate = a & b;
    wire [3:0] val_2_intermediate = ~val_3_intermediate;

    assign #14 gt = val_3_intermediate[0] ^ val_4_intermediate[0] ^ val_2_intermediate[0];
    assign #14 eq = val_3_intermediate[1] ^ val_4_intermediate[1] ^ val_2_intermediate[1];
    assign #14 lt = val_3_intermediate[2] ^ val_4_intermediate[2] ^ val_2_intermediate[2];
