module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] and_abcd;
    wire [3:0] or_abcd;
    wire [3:0] xor_abcd;
    wire [3:0] not_abcd;

    // AND gate with 20ns delay for each bit
    genvar j;
    generate
        for (j=0; j<4; j=j+1) begin : AND_GEN
            and #20 (and_abcd[j], a[j], b[j]);
        end
    endgenerate

    // OR gate with 20ns delay for each bit
    generate
        for (j=0; j<4; j=j+1) begin : OR_GEN
            or #20 (or_abcd[j], and_abcd[j], 1'b0);
        end
    endgenerate

    // XOR gate with 20ns delay for each bit
    generate
        for (j=0; j<4; j=j+1) begin : XOR_GEN
            xor #20 (xor_abcd[j], and_abcd[j], 1'b0);
        end
    endgenerate

    // NOT gate with 20ns delay for each bit
    generate
        for (j=0; j<4; j=j+1) begin : NOT_GEN
            not #20 (not_abcd[j], xor_abcd[j]);
        end
    endgenerate

    assign gt = &or_abcd;
    assign eq = &xor_abcd;
    assign lt = &not_abcd;
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    parameter [7:0] Grouper = "UNGROUPED";
    wire [3:0] intermediate;

    assign intermediate = a ^ b;
    assign gt = (Grouper == "UNGROUPED") ? 1'b1 :
                   (Grouper[0] ? (intermediate[0] ^ gt) : (intermediate[0] & gt));
    assign eq = (Grouper == "UNGROUPED") ? 1'b1 :
                   (Grouper[1] ? (intermediate[1] ^ eq) : (intermediate[1] & eq));
    assign lt = (Grouper == "UNGROUPED") ? 1'b1 :
                   (Grouper[2] ? (intermediate[2] ^ lt) : (intermediate[2] & lt));
endmodule

