  always @(posedge train_valid or posedge train_taken) begin
    if (train_taken) begin
      reg2 <= 2'b00;
    end else begin
      if (clk) begin
        reg2 <= 2'b11;
      end else if (reg1 == 2'b10) begin
        reg2 <= 2'b00;
      end else if (reg1 == 2'b01) begin
        reg2 <= 2'b01;
      end else begin
        reg2 <= reg2;
      end
    end
  end

  assign state = {reg1, reg2};

