        if (val_i)
          next_reg = reg [1:0] & {2{~train_valid}};
        else if (train_valid)
          next_reg = reg [1:0] | {2{~train_taken}};
        else
          next_reg = reg [1:0];
        (reg [1:0] <= next_reg) ? $display("Hazard for bit %0d", i) : ;
      end
    endgen
  endgenerate

  always @(posedge areset or posedge train_valid) begin
    if (train_valid) reg0 <= 2'b11;
    else reg0 <= clk;
