  wire [7:0] and_bits;
  wire [7:0] or_bits;

  genvar i;
  generate
    for (i=0; i<8; i=i+1) begin: gen_val2
      assign and_bits[i] = a[i] & b[i];
      assign or_bits[i] = a[i] | b[i];
      assign s[i] = and_bits[i] ^ or_bits[i];
    end
  endgenerate

  // Intermediate wires for overflow calculation
  wire [7:0] not_bits;
  wire [7:0] xor_bits;
  wire [7:0] and_bits;

  generate
    for (i=0; i<8; i=i+1) begin: gen_val3
      assign not_bits[i] = ~a[i];
      assign xor_bits[i] = not_bits[i] ^ b[i];
      assign and_bits[i] = xor_bits[i] & a[i];
    end
  endgenerate

  assign overflow = |and_bits;

endmodule

