  assign next_reg1 = clk ? reg2 :
                     j ? reg2 :
                     k ? reg2 : 1'b0;

  assign next_reg2 = areset ? reg1 :
                     clk ? reg1 :
                     j ? reg1 : 1'b0;

  // Update registers on posedge areset or posedge k
  always @(posedge areset, posedge k) begin
    if (areset) begin
      reg1 <= next_reg1;
      reg2 <= next_reg2;
    end else begin
      reg1 <= next_reg1;
      reg2 <= next_reg2;
