  // Gated-D Flip-Flop (k -> reg1 with enable j)
  always @(posedge j) begin
    reg1 <= k;
  end

  // NOT gate (reg0 -> not_reg1)
  assign not_reg1 = ~reg0;

  // AND gate (not_reg1 & reg1) -> out
  assign and_out = not_reg1 & reg1;

  // OR gate (k | j) -> out (conflict with and_out)
  assign or_out = k | j;
  assign out = or_out;

