    if (clk) reg0 = clk;
    // Update reg1 with new value if specified
    if (resetn) reg1 = resetn;
    // Update reg2 with new value if specified
    if (in) reg2 = in;

    reg2_next = reg2; // Assign to next register value

    // Priority-based override for reg2
    if (reg1)
      reg2_next = reg1;
    else if (reg0)
      reg2_next = reg0;
  end

  always @(posedge clk, posedge resetn, posedge in) begin
    if (clk) reg0 <= clk;
    else if (resetn) reg1 <= resetn;
    else if (in) reg2 <= reg2_next;
  end

