  localparam [2:0] zero = 3'b000,
                   s1   = 3'b001,
                   s11  = 3'b010,
                   s10  = 3'b011,
                   s100 = 3'b100;

  reg [2:0] current_state, next_state;

  // Update the state register (sequential logic)
  always @(posedge clk) begin
    current_state <= next_state;
  end

  // Next state logic (combinational)
  always @(*) begin
    case (current_state)
      zero: next_state = reset ? s1 : zero;
      s1:   next_state = w ? s11 : s10;
      s10:  next_state = w ? s101 : s100;
      s11:  next_state = w ? s11 : s10;
      s100: next_state = w ? s101 : s100;
      default: next_state = zero;
      default: next_state = zero;
    endcase
  end

  // Output logic
  assign z = (current_state == s11) ? 1'b1 :
                (current_state == s101) ? 1'b0 :
