module TopModule (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);

  reg [3:0] current_val;
  reg [3:0] next_val;

  always @* begin
    next_val = current_val;
    if (clk) begin
      if (current_val[0]) begin
        next_val[0] = 1'b0;
        if (current_val[3:1] != 3'b000)
          next_val[3:1] = current_val[3:1] - 1;
      end else begin
        next_val[0] = 1'b1;
        if (current_val[3:1] != 3'b000)
          next_val[3:1] = current_val[3:1] + 1;
      end
    end
    // Process shift_ena
    if (shift_ena) begin
      if (current_val[1] == next_val[1]) begin
        if (next_val[3:2] != 2'b00)
          next_val[3:2] = next_val[3:2] - 1;
        else
          next_val[3:2] = next_val[3:2] + 1;
      end else begin
        next_val[1:0] = 2'b00;
      end
    end
    // Process count_ena
    if (count_ena) begin
      if (current_val[2] == next_val[2]) begin
        if (next_val[3])
          next_val[3] = next_val[3] - 1;
        else
          next_val[3] = next_val[3] + 1;
      end else begin
        next_val[2:1] = 2'b00;
      end
    end
    // Process data
    if (data) begin
      if (current_val[3] == next_val[3]) begin
        if (next_val[3])
          next_val[3] = next_val[3] - 1;
        else
          next_val[3] = next_val[3] + 1;
      end else begin
        next_val[3:1] = 3'b000;
      end
    end
    // Determine new value
    current_val = next_val;
  end

  assign q = current_val;

  // Initialize to 5 (4'b0101)
  initial begin
    current_val = 4'b0101;
  end

endmodule

