module TopModule (
  input a,
  input b,
  input c,
  input d,
  input e,
  output [24:0] out
);
  // Process a (3 bits)
  wire signed [2:0] sum0 = a - (-2); // 3-bit signed -2 is -2
  wire signed [2:0] sum0_ext = $signed({3{3{a}}}) + (-2);
  wire signed [2:0] sum0_cgrundey = a - (-2);
  wire signed [2:0] sum0_jtg = a - (-2);

  // Process b (4 bits)
  wire signed [3:0] sum1 = b - (-3); // 4-bit signed -3 is -3
  wire signed [3:0] sum1_ext = $signed({4{4{b}}}) + (-3);
  wire signed [3:0] sum1_cgrundey = b - (-3);
  wire signed [3:0] sum1_jtg = b - (-3);

  // Process c (5 bits)
  wire signed [4:0] sum2 = c - (-4); // 5-bit signed -4 is -4
  wire signed [4:0] sum2_ext = $signed({5{5{c}}}) + (-4);
  wire signed [4:0] sum2_cgrundey = c - (-4);
  wire signed [4:0] sum2_jtg = c - (-4);

  // Process d (6 bits)
  wire signed [5:0] sum3 = d - (-5); // 6-bit signed -5 is -5
  wire signed [5:0] sum3_ext = $signed({6{6{d}}}) + (-5);
  wire signed [5:0] sum3_cgrundey = d - (-5);
  wire signed [5:0] sum3_jtg = d - (-5);

  // Process e (7 bits)
  wire signed [6:0] sum4 = e - (-6); // 7-bit signed -6 is -6
  wire signed [6:0] sum4_ext = $signed({7{7{e}}}) + (-6);
  wire signed [6:0] sum4_cgrundey = e - (-6);
  wire signed [6:0] sum4_jtg = e - (-6);

  // Concatenate results
  assign out = {sum0_ext, sum1_ext, sum2_ext, sum3_ext, sum4_ext};
endmodule

