module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg sync0_1 = 0;
  reg sync0_2 = 0;
  reg sync1_1 = 0;
  reg sync1_2 = 0;
  reg prev_sync1 = 0;

  always @(posedge clk) begin
    // Synchronize reset to clk domain
    sync0_1 <= reset;
    sync0_2 <= sync0_1;
  end

  always @(posedge clk) begin
    // Synchronize reset to reset domain
    sync1_1 <= reset;
    sync1_2 <= sync1_1;
  end

  // Edge detection for synchronized reset signal
  always @(posedge reset) begin
    prev_sync1 <= sync1_2;
  end

  wire edge_detected = (prev_sync1 == 1'b0) && (sync1_2 == 1'b1);

  // Update output based on data and edge detection
  reg val_3_reg;
  always @(posedge clk) begin
    if (data) begin
      val_3_reg <= 1'b0;
    end else begin
      if (edge_detected) begin
        val_3_reg <= reset;
      end else begin
        val_3_reg <= val_3_reg;
      end
    end
  end

  assign start_shifting = val_3_reg;

endmodule

