  reg output_reg;

  always @(posedge clk) begin
    // Synchronize reset and data to the input domain
    sync_1_reg <= reset;
    sync_2_reg <= data;

    // Track previous synchronized values for edge detection
    sync_2_prev <= sync_2_reg;

    // Counter control logic
    if (counter == 2'd2)
      counter <= 2'd0;
    else if (sync_2_prev == 1'b0 && sync_2_reg == 1'b1)
      counter <= counter + 1;
  end

  // Latch output based on counter
  always @(*) begin
    if (counter == 2'd2)
      output_reg = reset;
  end

  assign start_shifting = output_reg;

  // Reset counter and output when clk is low
  always @(posedge clk) begin
    if (!clk) begin
      counter <= 2'd0;
      output_reg <= 1'b0;
    end
  end

endmodule

