module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [4:0] sum_total = A + B + Cin;
    reg [3:0] sum_bcd;
    reg carry;

    always @(*) begin
        if (sum_total >= 5'd10) begin
            sum_bcd = sum_total - 5'd10;
            carry = 1;
        end else begin
            sum_bcd = sum_total[3:0];
            carry = 1'b0;
        end
    end

    assign Sum = sum_bcd;
    assign Cout = carry;

endmodule

