module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

parameter [2:0] IDLE = 2'b00;
parameter [2:0] A = 3'b001;
parameter [2:0] B = 3'b010;
parameter [2:0] C = 3'b011;
parameter [2:0] D = 3'b100;

reg [2:0] current_state, next_state;

// State transition (sequential process)
always @(posedge rst_n or negedge a) begin
	if (!a)
		current_state <= IDLE;
	else
		current_state <= next_state;
end

// Next state logic (combinational process)
reg [2:0] next_state;
always @* begin
	case (current_state)
		IDLE: next_state = clk ? A : IDLE;
		A: next_state = clk ? B : IDLE;
		B: next_state = clk ? C : IDLE;
		C: next_state = clk ? D : IDLE;
		D: next_state = clk ? E : IDLE;
		E: next_state = clk ? F : IDLE;
		F: next_state = clk ? G : IDLE;
		G: next_state = clk ? H : IDLE;
		H: next_state = clk ? I : IDLE;
		I: next_state = clk ? J : IDLE;
		J: next_state = clk ? K : IDLE;
		K: next_state = clk ? L : IDLE;
		L: next_state = clk ? M : IDLE;
		M: next_state = clk ? N : IDLE;
		N: next_state = clk ? O : IDLE;
		O: next_state = clk ? P : IDLE;
		P: next_state = clk ? Q : IDLE;
		Q: next_state = clk ? R : IDLE;
		R: next_state = clk ? S : IDLE;
		S: next_state = clk ? T : IDLE;
		T: next_state = clk ? U : IDLE;
		U: next_state = clk ? V : IDLE;
		V: next_state = clk ? W : IDLE;
		W: next_state = clk ? X : IDLE;
		X: next_state = clk ? Y : IDLE;
		Y: next_state = clk ? Z : IDLE;
		Z: next_state = clk ? A : IDLE;
		default: next_state = IDLE;
	}
end

// Output logic (sequential process)
always @(posedge rst_n or negedge a) begin
	if (!a) begin
		rise <= 1'b0;
		down <= 1'b0;
	end
	else begin
		rise <= (next_state == X) ? 1'b1 : 1'b0;
		down <= (next_state == O) ? 1'b1 : 1'b0;
	end
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    localparam COUNTER_WIDTH = (NUM_DIV == 0) ? 1 : $clog2(NUM_DIV + 1);
    reg [COUNTER_WIDTH-1:0] counter;

    always @(posedge rst_n or negedge clk) begin
        if (!clk) begin
            counter <= 0;
            clk_div <= 0;
        end else begin
            if (counter == NUM_DIV) begin
                clk_div <= ~clk_div;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    assign clk_div = clk_div;

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [1:0] counter;
    reg [1:0] prev_bits;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Active-low reset
            counter <= 2'd0;
            prev_bits <= 2'd0;
            clk_div <= 1'b0;
        end else begin
            // Default assignments for assignments
            counter <= counter;
            prev_bits <= prev_bits;

            if (counter == (NUM_DIV >> 1)) begin
                clk_div <= ~clk_div;
                counter <= 2'd0;
            end else begin
                counter <= counter + 2'd1;
            end

            // Check for rising edge of clk
            if (prev_bits[0] == 1'b0 && clk == 1'b1) begin
                if (counter == (NUM_DIV - 2'd1)) begin
                    clk_div <= ~clk_div;
                end
                counter <= 2'd0;
            end else begin
                prev_bits <= {prev_bits[0]^(prev_bits[0] ^ clk), clk};
            end
        end
    end

endmodule

module freq_divbyeven(
