    assign clk_div = clk_div; // Continuous assignment for output

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            if (counter == NUM_DIV) begin
                clk_div <= ~clk_div;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end else begin
            counter <= 0;
        end
    end

    initial begin
        clk_div = 0;
        counter = 0;
    end
endmodule

