    localparam [4:0] COUNTER_WIDTH = (NUM_DIV == 0) ? 5'd0 : $clog2(NUM_DIV + 1);
    reg [4:0] count_reg;

    always @(posedge rst_n or negedge clk) begin
        if (~clk) begin
            count_reg <= 5'd0;
            clk_div <= 1'b0;
        end else begin
            if (count_reg == NUM_DIV) begin
                count_reg <= 5'd0;
                clk_div <= ~clk_div;
            end else begin
