module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [4:0] counter;

    // Counter logic with asynchronous reset and synchronous increment on rst_n's rising edge
    always @(posedge rst_n or negedge clk) begin
        if (!clk) begin
            counter <= 5'd0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 5'd0;
            end else begin
                counter <= counter + 1'd1;
            end
        end
    end

    // Output logic: high when lower 5 bits of counter are all 1s
    assign clk_div = (counter[4:0] == 5'b11111);

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

    // Internal registers for intermediate outputs
    reg [2:0] ins;
    reg [4:0] ad1;
    reg [7:0] ad2;

    always @(*) begin
        // Update outputs based on fetch (one-hot)
        case (fetch)
            2'b00: begin
                ins = {3{clk}};
                ad1 = {5{rst}};
                ad2 = {6{rst}};
            end
            2'b01: begin
                ins = data[2:0];
                ad1 = data[4:0];
                ad2 = data;
            end
            default: ; // No change for other cases
        endcase
    end

endmodule

