  output reg [3:0] out;
  reg [3:0] e0;
  reg [3:0] e1;
  reg [3:0] e2;

  always @(posedge clk) begin
    e0 <= {4{rst}};  // e0 updates with rst on clk's rising edge
  end

  always @(posedge rst) begin
    e1 <= e0;          // e1 takes previous e0's value on rst's rising edge
  end

  always @(posedge rst) begin
    e2 <= e1;          // e2 takes previous e1's value on rst's rising edge
  end

  always @(posedge clk) begin
    out <= e2;       // out updates with e2's value on clk's rising edge
  end

