    // Assign outputs with 20ns delay based on valid_out's changes
    assign #20 int_wire[0] = valid_out ? 1'b0 : (dout ? int_wire3[0] : dout);
    assign #20 int_wire[1] = valid_out ? 1'b0 : (dout ? int_wire3[1] : dout);

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [3:0] val_4_reg;
    reg val_3_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            val_4_reg <= 4'b0;
            val_3_reg <= 1'b0;
        end else begin
            val_4_reg <= d;
            val_3_reg <= val_4_reg;
        end
    end

    assign valid_out = val_3_reg;
    assign dout = val_4_reg;

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [3:0] inner_reg;
    reg [3:0] outer_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            inner_reg <= 4'b0;
        end else begin
            inner_reg <= { inner_reg[2:0], (inner_reg[0] & d[0]) } << 1;
        end
    end

    always @(posedge rst_n or negedge clk) begin
        if (!clk) begin
            outer_reg <= 4'b0;
        end else begin
            outer_reg <= { 4{inner_reg[3]}};
        end
    end

    assign valid_out = inner_reg[3];
    assign dout = outer_reg[3];

endmodule

